/**
 * Segment appender helper.
 *
 * Appends media data (ArrayBuffer or AsyncIterable<Uint8Array> stream) to a SourceBuffer, waiting for `updateend`
 * between calls so the browser can process each append before the next one arrives.
 */

import type { SegmentData } from '../../types';

/** Data accepted by appendSegment — the MSE-boundary alias of {@link SegmentData}. */
export type AppendData = SegmentData;

/**
 * Append media data to a SourceBuffer.
 *
 * Accepts either a full ArrayBuffer (single append) or an AsyncIterable of Uint8Array chunks (one append per chunk, in
 * order). Waits for `updateend` between each call so appends are serialized correctly.
 *
 * Errors from the SourceBuffer (`error` event) or from the iterable are propagated as rejections.
 */
export async function appendSegment(sourceBuffer: SourceBuffer, data: AppendData, signal?: AbortSignal): Promise<void> {
  if (data instanceof ArrayBuffer) {
    await appendChunk(sourceBuffer, data);
  } else {
    try {
      for await (const chunk of data) {
        // Check between chunks so an abort can stop streaming before the next
        // appendBuffer call. The current chunk (if any) has already landed in the
        // SourceBuffer; the partial: true flag in the actor model reflects this.
        if (signal?.aborted) throw signal.reason ?? new DOMException('Aborted', 'AbortError');

        await appendChunk(sourceBuffer, chunk);
      }
    } catch (e) {
      // Reset the MSE segment parser on any abort to discard partial fMP4 box
      // data from the SourceBuffer's internal byte buffer. Two paths reach here:
      //
      // 1. Explicit abort check above (signal.aborted between chunks) — the
      //    last appended chunk may have left the parser mid-fragment.
      //
      // 2. The fetch was cancelled (signal fired), causing the underlying
      //    ReadableStream to error and the for-await loop to throw directly
      //    without ever passing through the signal check above. Same cleanup
      //    is needed: partial box data must be cleared before the next append.
      //
      // Without this, the next appendBuffer call sees stale partial data and
      // Chrome throws CHUNK_DEMUXER_ERROR_APPEND_FAILED.
      if (e instanceof DOMException && e.name === 'AbortError' && !sourceBuffer.updating) {
        try {
          sourceBuffer.abort();
        } catch {
          // Thrown if the MediaSource is not "open" (e.g. during teardown).
        }
      }

      throw e;
    }
  }
}

async function appendChunk(sourceBuffer: SourceBuffer, data: ArrayBuffer | Uint8Array<ArrayBufferLike>): Promise<void> {
  if (sourceBuffer.updating) {
    await new Promise<void>((resolve) => {
      const onUpdateEnd = () => {
        sourceBuffer.removeEventListener('updateend', onUpdateEnd);
        resolve();
      };

      sourceBuffer.addEventListener('updateend', onUpdateEnd);
    });
  }

  return new Promise<void>((resolve, reject) => {
    const onUpdateEnd = () => {
      cleanup();
      resolve();
    };

    const onError = (event: Event) => {
      cleanup();
      reject(new Error(`SourceBuffer append error: ${event.type}`));
    };

    const cleanup = () => {
      sourceBuffer.removeEventListener('updateend', onUpdateEnd);
      sourceBuffer.removeEventListener('error', onError);
    };

    sourceBuffer.addEventListener('updateend', onUpdateEnd);
    sourceBuffer.addEventListener('error', onError);

    try {
      sourceBuffer.appendBuffer(data as ArrayBuffer);
    } catch (error) {
      cleanup();
      reject(error);
    }
  });
}
